"""stages.review.report: generated by the graph.py split (P1)."""

from __future__ import annotations

from pathlib import Path

from ...benchmark import embench
from ...flow import gates as gates_mod, optimize
from ...runtime import failures, llm, provenance, request_usage, stage_services
from ...state import CfuDesignState


def render_ladder(state: CfuDesignState) -> str:
    """Per-rung status of the validation ladder."""
    gates = state.get("gates", {}) or {}
    attempts = state.get("attempts", {}) or {}
    lines: list[str] = []
    rungs = ("isa", "implementation_hw", "hw_build", "hw_conformance",
             "implementation_sw", "sw_build", "sim", "cost")
    for rung in rungs:
        gate = gates.get(rung)
        if not isinstance(gate, dict):
            lines.append(f"- {rung}: not reached")
            continue
        if gate.get("disabled"):
            status = f"DISABLED by ablation ({gate.get('reason') or gate.get('disabled')})"
        elif gate.get("skipped"):
            status = f"skipped ({gate.get('reason', '')})"
        else:
            status = "pass" if gate.get("ok") else "FAIL"
        repairs = attempts.get(rung, 0)
        suffix = f", repairs={repairs}" if repairs else ""
        lines.append(f"- {rung}: {status}{suffix}")
    stopped = state.get("stopped_at", "")
    if stopped:
        lines.append(f"- stopped at: {stopped}")
    lines.append(
        f"- repairs used: {state.get('repairs_used', 0)}/{gates_mod.max_repairs(state)} "
        f"(iteration={state.get('iteration', 0)})"
    )
    return "\n".join(lines)


def ablation_lines(state: CfuDesignState) -> list[str]:
    """The ablation switches this run enabled and what each one removed.

    An ablated capability is never silently absent: the report and the CLI
    summary both say which flag disabled which check or evidence source.
    """
    active: list[str] = []
    if not state.get("llvm_ir", True):
        active.append(
            "- `--no-llvm-ir`: LLVM IR content removed (ir_features forced off; "
            "inspect_observation keeps only asm/summary views)"
        )
    if not state.get("require_conformance", True):
        active.append(
            "- `--no-conformance`: conformance requirement dropped (hw_conformance "
            "rung recorded as disabled, never validated)"
        )
    if not state.get("isa_contract", True):
        active.append(
            "- `--no-isa-contract`: ISA contract stage skipped; the agent authored "
            "`cfu_intrinsics.h` itself from the intrinsic template (encodings free)"
        )
    return active


def measurement_lines(state: CfuDesignState) -> list[str]:
    """Auditable Embench timing scope, distinct from integrity/semantic evidence."""
    project = state.get("benchmark_project") or {}
    sim = (state.get("gates") or {}).get("sim") or {}
    if not (project.get("kind") == "embench_benchmark" or state.get("benchmark_name")
            or sim.get("measurement_protocol") or sim.get("measurement")):
        return []
    measurement = sim.get("measurement") or project.get("measurement") or {}
    protocol = str(sim.get("measurement_protocol") or measurement.get("protocol") or "legacy")
    lines = [f"- measurement_protocol: {protocol}"]
    if sim.get("terminal_reason"):
        view = provenance.performance_view(state) if state.get("run_root") else {}
        current = view.get("current_performance") or {}
        matched = not view or current.get("performance_valid") is True
        label = "current simulation outcome" if matched else "last observed simulation outcome"
        lines.append(f"- {label}: {sim['terminal_reason']}")
        lines.append(f"- correctness_ok: {sim.get('correctness_ok') if matched else None}; timing_ok: {sim.get('timing_ok') if matched else None}; "
                     f"performance_valid: {sim.get('performance_valid') if matched else False}")
        if not matched or sim.get("performance_valid") is False:
            lines.append("- speedup: unavailable (this attempt has no trustworthy valid performance result)")
        if view and view.get("last_observed_valid_performance"):
            lines.append(f"- last_observed_valid_performance: {view['last_observed_valid_performance']}")
    if protocol == embench.MEASUREMENT_PROTOCOL:
        lines.extend([
            "- measurement: cold single invocation; no warmup; local_scale_factor=1; "
            "global_scale_factor=1",
            "- timing scope: includes original preparation, memory and CFU configuration; "
            "not pure math-kernel latency",
            "- comparability: new and legacy Embench measurements are not comparable",
        ])
    elif protocol == "legacy":
        lines.append("- measurement: legacy (protocol evidence absent); not comparable with "
                     "cold single invocation; start a new run rather than resume legacy evidence")
    else:
        lines.append("- measurement: recorded protocol differs from the current Embench default; "
                     "do not combine measurements from different protocols")
    if measurement:
        lines.append(f"- measurement metadata: {measurement}")
    integrity = sim.get("benchmark_integrity") or {}
    if integrity:
        status = "pass" if integrity.get("ok") is True else "FAIL" if integrity.get("ok") is False else "unknown"
        lines.append(f"- integrity gate status: {status}")
        lines.append(f"- integrity gate evidence: {integrity}")
    else:
        lines.append("- integrity gate status: not recorded (not inferred from sim success)")
    if project.get("integrity"):
        lines.append(f"- integrity guard metadata: {project['integrity']}")
    lines.append("- integrity checks protect scaffold/oracle bytes; passing them is not proof of "
                 "true operation equivalence or an arbitrary semantic anti-cheat guarantee")
    return lines


def render_report(state: CfuDesignState) -> str:
    lines: list[str] = [
        "# CFU Design Agent Report",
        f"Task: {state.get('task', '')}",
        f"Status: {state.get('status', '')}",
        f"Termination: {state.get('termination_reason', '')}",
        f"Run root: {state.get('run_root', '')}",
        "",
    ]
    llm_request = state.get("llm_request") or {}
    if llm_request:
        lines.extend([
            "## LLM Request",
            f"- config: {llm_request.get('config', '')}",
            f"- model: {llm_request.get('model', '')}",
            f"- base_url: {llm_request.get('base_url', '')}",
            f"- api_mode: {llm_request.get('api_mode', '')}",
            f"- thinking: {llm_request.get('thinking')}",
            f"- reasoning_effort: {llm_request.get('reasoning_effort')}",
            f"- max_output_tokens: {llm_request.get('max_output_tokens')}",
            "",
        ])
    context = state.get("context") or {}
    visibility = str(state.get("visibility") or context.get("visibility") or "")
    if visibility:
        lines.extend([
            "## Visibility",
            f"- level: {visibility}",
            "- scope: read-only file visibility for the agent (writes and command "
            "allowlists are unaffected)",
        ])
        withheld = list(context.get("withheld") or [])
        if withheld:
            lines.append("- withheld from the agent at this level:")
            lines.extend(f"  - {item}" for item in withheld)
        lines.append("")
    ablation = ablation_lines(state)
    if ablation:
        lines.append("## Ablation")
        lines.extend(ablation)
        lines.append("")
    if state.get("termination"):
        lines.extend(["## Typed Termination", f"- termination: {state['termination']}", ""])
    view = provenance.performance_view(state)
    if state.get("run_root"):
        lines.extend(["## Performance Provenance",
                      f"- current_performance: {view['current_performance']}",
                      f"- last_observed_valid_performance: {view['last_observed_valid_performance']}", ""])
    lines.append("## Gates")
    for key, value in (state.get("gates") or {}).items():
        lines.append(f"- {key}: {value}")
    lines.append("")
    lines.append("## Validation Ladder")
    lines.append(render_ladder(state))
    lines.append("")
    rounds = state.get("optimization_rounds") or []
    if rounds:
        best = optimize._best_round(rounds) or {}
        best_index = best.get("round")
        final_index = rounds[-1].get("round")
        lines.append("## Optimization Rounds")
        lines.append(
            f"- mode: --loop, {len(rounds)} recorded result(s), best round "
            f"{best_index}, final round {final_index}"
        )
        if (
            best_index is not None
            and final_index is not None
            and best_index != final_index
            and rounds[-1].get("measured")
        ):
            # Only a measured final round can be called a regression; a round with
            # no measurement of its own shows up as "not measured" and the run's
            # status already reports that it failed.
            lines.append(
                "- WARNING: the final round is not the best round; it may be equivalent, "
                "worse, or a speed/area tradeoff. The workspace belongs to the final experiment; "
                "use the validated candidate snapshot below for the selected source delivery."
            )
        for index, entry in enumerate(rounds):
            lines.append(
                f"- round {entry.get('round')}: {entry.get('target')} "
                + optimize._round_metrics_text(entry)
                + optimize._metric_deltas(entry, optimize._previous_measured(rounds, index))
                # The baseline is the reference point, not an "improvement".
                + (f" improved={bool(entry.get('improved'))}" if entry.get("round") else "")
                + (" (best)" if entry.get("round") == best_index else "")
                + (f" — {entry.get('reason')}" if entry.get("reason") else "")
            )
        lines.append("")
    candidate = state.get("best_candidate") or {}
    if candidate:
        lines.extend(["## Selected Validated Candidate",
                      f"- delivered source round: {candidate.get('round')}",
                      f"- manifest (ISA, source hashes and validation evidence): {candidate.get('manifest')}",
                      "- These are immutable validated source inputs, not a claim that the final workspace/binaries were restored.", ""])
    lines.append("## Normalized WorkloadSpec")
    lines.append("```yaml")
    lines.append(state.get("spec_text", "").strip())
    lines.append("```")
    lines.append("")
    lines.append("## Benchmark Project")
    lines.append(format_mapping(state.get("benchmark_project", {})))
    lines.append("")
    measurement = measurement_lines(state)
    if measurement:
        lines.append("## Embench Measurement and Integrity")
        lines.extend(measurement)
        lines.append("")
    lines.append("## Profile Result")
    lines.append(format_mapping(state.get("profile_result", {})))
    lines.append("")
    lines.append("## Workload Analysis")
    lines.append(str(state.get("workload_analysis", "")))
    if state.get("ir_features", "off") != "off" and state.get("llvm_ir", True):
        ir = state.get("ir_result") or {}
        lines.append("\n### LLVM IR evidence (static, optional)")
        lines.append(f"- status: {ir.get('status', 'unavailable')}")
        lines.append(f"- reason: {ir.get('reason', '')}")
        lines.append(f"- target_match: {ir.get('toolchain', {}).get('target_match', False)}")
        lines.append("- metadata: 07_analysis/ir_features.yaml")
        lines.extend(f"- IR: {path}" for path in ir.get("ir_files", []))
        lines.extend(f"- features: {path}" for path in ir.get("feature_files", []))
    lines.append("")
    lines.append("## CFU ISA Spec")
    if not state.get("isa_contract", True):
        lines.append(
            "Disabled by `--no-isa-contract`: no contract was authored. The agent wrote "
            "`cfu_intrinsics.h` itself from the intrinsic template (free encodings); the "
            "header is the instruction interface."
        )
    elif state.get("isa_spec"):
        import yaml as _yaml
        lines.append("```yaml")
        lines.append(_yaml.safe_dump(state["isa_spec"], sort_keys=False).strip())
        lines.append("```")
    else:
        lines.append("No ISA spec was produced.")
    if state.get("isa_spec_errors"):
        lines.append("### ISA errors")
        lines.append("\n".join(f"- {err}" for err in state["isa_spec_errors"]))
    lines.append("")
    lines.append("## Hardware Design")
    lines.append(str(state.get("implementation_hw_summary", "")))
    lines.append("")
    lines.append("## Software Design")
    lines.append(str(state.get("implementation_sw_summary", "")))
    lines.append("")
    lines.append("## Hardware Build (SoC generation)")
    lines.append(format_rung_results(state, "hw_build"))
    lines.append("")
    lines.append("## Software Build (compile)")
    lines.append(format_rung_results(state, "sw_build"))
    lines.append("")
    lines.append("## Simulation")
    lines.append(format_rung_results(state, "sim"))
    lines.append("")
    lines.append("## Hardware Cost")
    lines.append(format_results(state.get("cost_results", [])))
    lines.append("")
    lines.append("## Tool Calls")
    tool_calls = state.get("tool_calls") or []
    if tool_calls:
        for call in tool_calls:
            lines.append(
                f"- round {call.get('round')}: `{call.get('tool')}`"
                f"({call.get('arguments')}) ok={call.get('ok')}"
                f" result_chars={call.get('result_chars')}"
            )
    else:
        lines.append("No agent tool calls were recorded for this run.")
    lines.append("")
    lines.append("## LLM Raw Outputs")
    raw_outputs = state.get("llm_raw_outputs", [])
    if raw_outputs:
        lines.extend(f"- `{path}`" for path in raw_outputs)
    else:
        lines.append("No LLM calls were recorded for this run.")
    lines.append("")
    lines.append("## Token Usage")
    usage = state.get("token_usage") or llm.usage_totals()
    audit = state.get("request_usage") or {}
    if not audit and state.get("run_root"):
        audit = request_usage.load_request_usage(
            Path(state.get("workdir", ".")) / state["run_root"] / "request_audit.jsonl")
    if audit:
        usage = {"calls": audit["calls"], "input": audit["input_tokens"],
                 "output": audit["output_tokens"], "total": audit["total_tokens"]}
    lines.append(f"- llm_calls: {usage['calls']}")
    lines.append(f"- input tokens: {usage['input'] if usage['input'] is not None else 'n/a'}")
    lines.append(f"- output tokens: {usage['output'] if usage['output'] is not None else 'n/a'}")
    lines.append(f"- total tokens: {usage['total'] if usage['total'] is not None else 'n/a'}")
    if audit:
        lines.extend([f"- token usage source: {audit['source']}",
                      f"- cached input tokens: {audit['cached_input_tokens']}",
                      f"- known usage (lower bound): {audit['known_usage']}",
                      f"- missing usage requests: {audit['missing_usage_requests']}"])
    lines.append("")
    by_stage = state.get("token_usage_by_stage") or llm.usage_by_stage()
    if by_stage:
        lines.append("Per stage (sorted by input tokens, largest first):")
        lines.append("")
        lines.append("| stage | calls | input | output | total |")
        lines.append("| --- | ---: | ---: | ---: | ---: |")
        for name, bucket in sorted(
            by_stage.items(), key=lambda item: (-int(item[1].get("input", 0)), item[0])
        ):
            lines.append(
                f"| {name} | {bucket.get('calls', 0)} | {bucket.get('input', 0)} "
                f"| {bucket.get('output', 0)} | {bucket.get('total', 0)} |"
            )
        lines.append("")
    lines.append("## LLM Prompts")
    run_root = Path(str(state.get("run_root", "") or ""))
    prompt_files = sorted(run_root.glob("**/llm_raw/*.prompt.txt")) if str(run_root) else []
    if prompt_files:
        lines.extend(f"- `{path.relative_to(run_root)}`" for path in prompt_files)
    else:
        lines.append("No prompts were recorded for this run.")
    lines.append("")
    lines.append("## Iteration History")
    lines.append("\n".join(f"- {line}" for line in state.get("iteration_history", [])))
    lines.append("")
    if state.get("report_warnings"):
        lines.extend(["## Report Warnings", *[f"- {warning}" for warning in state["report_warnings"]], ""])
    lines.append("## Errors")
    lines.append("\n".join(f"- {err}" for err in state.get("errors", [])) or "None")
    return "\n".join(lines) + "\n"


def write_partial_report(initial_state: CfuDesignState, exc: Exception) -> CfuDesignState:
    """Persist an exceptional run without routing it as a validated result.

    The runner/wrapper provide observed state. Input-only fallback is labelled as
    such; no unobserved gate verdict, candidate metric or budget is fabricated.
    """
    import traceback

    state = {**initial_state, **(getattr(exc, "partial_state", None) or {})}
    typed = failures.termination(exc)
    typed.setdefault("state_source", "cli_input")
    state.update(status="failed", termination_reason={
        "model_delivery_failure": "MODEL_DELIVERY_FAILURE",
        "infrastructure": "INFRASTRUCTURE_EXCEPTION",
        "precondition": "PRECONDITION_FAILURE",
    }.get(typed["kind"], "RUNTIME_EXCEPTION"), termination=typed,
                 token_usage=state.get("token_usage") or llm.usage_totals(),
                 token_usage_by_stage=state.get("token_usage_by_stage") or llm.usage_by_stage())
    if typed.get("stage"):
        state["stopped_at"] = typed["stage"]
    state["errors"] = [*(state.get("errors") or []), f"{typed['exception_type']}: {typed['reason']}"]
    artifacts = stage_services._artifacts(state, stage_services._policy(state))
    state.update(run_id=artifacts.run_id, run_root=artifacts.root_rel)
    state["llm_request"] = artifacts.manifest.get("llm_request") or state.get("llm_request") or {}
    warnings: list[str] = []
    audit = request_usage.load_request_usage(artifacts.root / "request_audit.jsonl", warnings)
    if audit:
        state["request_usage"] = audit
    state["report_warnings"] = warnings
    artifacts.write_json("review", "12_review/termination.json", typed, status="failed")
    artifacts.write_text("review", "12_review/exception.txt", "".join(traceback.format_exception(exc)), status="failed")
    artifacts.set_manifest_metadata("review", "termination", typed)
    artifacts.set_manifest_metadata("review", "token_usage", state["token_usage"])
    if audit:
        artifacts.set_manifest_metadata("review", "request_usage", audit)
    artifacts.write_text("review", "report.md", render_report(state), kind="markdown", status="failed")
    artifacts.set_status("review", "failed", error=f"{typed['exception_type']}: {typed['reason']}")
    state["final_report_path"] = str(artifacts.path("report.md"))
    return state


def format_rung_results(state: CfuDesignState, rung: str) -> str:
    results = [r for r in (state.get("validation_results") or []) if r.get("rung") == rung]
    return format_results(results)


def format_results(results: list[dict]) -> str:
    if not results:
        return "No results."
    lines: list[str] = []
    for result in results:
        lines.append(f"- `{result.get('command', '')}` rc={result.get('returncode')}")
        if result.get("skipped"):
            lines.append(f"  skipped: {result.get('reason', '')}")
        parsed = result.get("parsed")
        if parsed:
            lines.append(f"  parsed: {parsed}")
        stdout_tail = result.get("stdout_tail", "").strip()
        if stdout_tail:
            lines.append("  stdout tail:")
            lines.append("  ```text")
            lines.append(stdout_tail[-1200:])
            lines.append("  ```")
    return "\n".join(lines)


def format_mapping(value: dict) -> str:
    if not value:
        return "No data."
    lines = []
    for key, item in value.items():
        lines.append(f"- {key}: {item}")
    return "\n".join(lines)
